'use client'

import { useFavorites } from '@/lib/hooks/use-favorites'

export function FavoriteButton({ slug, name }: { slug: string; name: string }) {
  const { toggle, isFavorite } = useFavorites()
  const favorited = isFavorite(slug)

  return (
    <button
      onClick={(e) => {
        e.preventDefault()
        e.stopPropagation()
        toggle(slug)
      }}
      className="p-2 shrink-0 cursor-pointer transition-colors"
      aria-label={favorited ? `Remove ${name} from favorites` : `Add ${name} to favorites`}
      style={{ minHeight: '44px', minWidth: '44px' }}
    >
      <svg className="w-5 h-5" viewBox="0 0 24 24" aria-hidden="true"
        fill={favorited ? 'currentColor' : 'none'}
        stroke="currentColor"
        strokeWidth={favorited ? 0 : 1.5}
      >
        <path
          className={favorited ? 'text-amber-400' : 'text-slate-400 dark:text-slate-600'}
          d="M11.049 2.927c.3-.921 1.603-.921 1.902 0l1.519 4.674a1 1 0 00.95.69h4.915c.969 0 1.371 1.24.588 1.81l-3.976 2.888a1 1 0 00-.363 1.118l1.518 4.674c.3.922-.755 1.688-1.538 1.118l-3.976-2.888a1 1 0 00-1.176 0l-3.976 2.888c-.783.57-1.838-.197-1.538-1.118l1.518-4.674a1 1 0 00-.363-1.118l-3.976-2.888c-.784-.57-.38-1.81.588-1.81h4.914a1 1 0 00.951-.69l1.519-4.674z"
        />
      </svg>
    </button>
  )
}
